/*
 * Long-form documentation prose, keyed by the English source sentence itself.
 *
 * Why keyed by source, when the section dictionaries are keyed by symbol:
 *
 *  - A documentation page is a hundred sentences written in place, next to the
 *    component they describe. Moving every one of them behind a symbol would
 *    mean a translator has to open a page to find out what a key means, and a
 *    reviewer can no longer read the English source and the translation side by
 *    side. Keeping the English where it is written — and looking the Chinese up
 *    by that sentence — is the same trick the navigation labels have used since
 *    Phase 2, applied to the body copy.
 *  - Identical sentences are translated once. "Nothing is computed here."
 *    appears on four pages; it has one Chinese rendering, so the Showcase cannot
 *    drift into two different translations of the same sentence.
 *
 * The English source stays in the page and is the fallback, so a sentence that
 * is missing from this file renders in English rather than as a key. Coverage is
 * measured, not asserted: `scripts/i18n-coverage.mjs` walks every page, extracts
 * each translatable sentence and fails if one of them is absent here.
 *
 * Never translated: component names, prop names, import paths, code samples,
 * token names and CSS custom properties. Those are identifiers a developer types
 * verbatim in either language.
 *
 * Editorial glossary (keep these renderings consistent across pages):
 *
 *   surface      → 表面            token            → 令牌
 *   elevation    → 层级            personality      → 视觉人格
 *   press / lift → 按压 / 抬升      reduced motion   → 减弱动效
 *   overlay      → 覆盖层          focus ring       → 焦点环
 *   recipe       → 配方            contract         → 契约
 *   fixture      → 固定数据         caller           → 调用方
 *   composed     → 组合            works with       → 配合使用
 */

