  "Provider data may be delayed or end-of-day depending on the market and your data agreement.":
    "提供商数据可能延迟，或按市场与你所签数据协议改为收盘口径。",
  "Runs are stored locally": "运行存储在本地",
  "External resources": "外部资源",
  "Actions and dismissal": "操作与关闭",
  "Widget dismissed": "挂件已关闭",
  "The consumer owns the persistence — LUC does not remember a dismissal.":
    "持久化由调用方负责——LUC 不会记住「已关闭」。",
  "Market widget unavailable": "行情挂件不可用",
  "TradingView could not be reached. The rest of this page is unaffected.":
    "无法连接到 TradingView。本页其余内容不受影响。",
  "Saved": "已保存",
  "Next to a form": "在表单旁边",
  "A page-level Alert and a form's own error summary answer different questions; they can sit together without repeating each other.":
    "页面级 Alert 与表单自己的错误摘要回答的是不同的问题；它们可以并存而互不重复。",
  "Server-side validation also runs on submit": "提交时服务端也会再校验一次",
  "Client rules are a courtesy; the stored dataset is validated again.":
    "客户端规则只是礼貌；真正入库的数据集会被再校验一次。",
  "Dataset name": "数据集名称",
  "Lowercase, no spaces.": "小写，不含空格。",

  /* ----------------------------------------------------------- components/alert-dialog */
  "312 rows and every derived analytics partition will be removed. This cannot be undone.":
    "312 行以及所有派生的分析分区都会被删除。此操作无法撤销。",
  "Publishing moves the live pointer. The previous generation stays readable until retention walks it.":
    "发布只会移动线上指针。上一代在被保留策略回收之前仍然可读。",
  "Links keep working; the slug changes immediately.": "链接继续有效；slug 会立即改变。",
  "Name the action (“Delete dataset”), never “OK”.": "按钮要写明动作（「删除数据集」），永远不要写「确定」。",
  "Say what is lost and whether it can be undone.": "说明会失去什么，以及能否撤销。",
  "Reserve it for a decision that cannot be reverted in place.":
    "只留给无法就地撤销的决定。",
  "Use it for a confirmation that could be a Button with an undo.":
    "把它用在「一个按钮配撤销」就能解决的确认上。",
  "Stack two alert dialogs — one decision per moment.": "叠两个警示对话框——每个时刻只做一个决定。",
  "Put an irreversible action in the first focus position.":
    "把不可逆操作放在第一个焦点位置。",
  "A confirmation is a decision, not a page.": "确认是一个决定，不是一个页面。",
  "The safe reading of a confirmation is a destructive one.":
    "确认按钮的安全读法应当是破坏性的那个。",
  "They close the dialog; the work stays in your handler.": "它们只负责关闭对话框；工作留在你的处理函数里。",
  "Radix removes outside-click dismissal from the contract entirely.":
    "Radix 直接把「点击外部关闭」从契约里移除。",

  /* --------------------------------------------------------------- components/accordion */
  "Components": "组件",
  "API": "API",
  "Every provider wrote inside its window. 1,284 bars landed for BTCUSDT 1h and the 1d rollup matched the hourly sum to the tick.":
    "每个提供商都在自己的窗口内写入。BTCUSDT 1h 落地 1,284 根 K 线，日线汇总与小时合计逐笔一致。",
  "Seven domains validated against their expected row counts.": "七个域已按预期行数校验通过。",
  "A new generation was published. The previous one stays readable until retention walks it.":
    "新一代已发布。上一代在被保留策略回收之前保持可读。",
  "Is the panel animated?": "面板有动画吗？",
  "Yes — Radix measures the panel and LUC animates to that height. Under reduced motion the panel is simply open or closed.":
    "有——Radix 测量面板，LUC 动画到那个高度。减弱动效下面板就是简单开与关。",
  "Does collapsing unmount the content?": "折叠会卸载内容吗？",
  "It does. State that must survive a collapse belongs above the accordion, or behind":
    "会。必须跨折叠存活的状态应该放在手风琴之上，或放在",
  "Publish on partial data": "在数据不完整时发布",
  "Collapsible is the same disclosure without the item wrapper.":
    "Collapsible 是同一套展开逻辑，但没有 item 包装。",
  "Radix's own contract: how many sections may be open.": "Radix 自己的契约：允许同时展开几个分区。",
  "In single mode, allow closing the open item.": "在单开模式下，允许关闭已展开的那一项。",
  "Own surface, or one surface with hairlines.": "各自独立表面，或一个表面加细线分隔。",
  "Leading and right-aligned slots before the chevron.": "在箭头之前的左右两个槽位。",
  "Inner padding; off for a list or a table.": "内边距；列表或表格时关闭。",
  "One region, no item and no roving focus.": "一个区域，没有 item，也没有游走焦点。",

