  /* ------------------------------------------------------------- charts/uncertainty */
  "Charts · Uncertainty": "图表 · 不确定性",
  "Fan chart": "扇形图",
  "Nested quantile bands on one hue: the shared colour says 'the same estimate', the layered opacity says 'how far from the centre'.":
    "同一色相上的嵌套分位带：统一的颜色表示「同一个估计」，分层的透明度表示「离中心有多远」。",
  "Bootstrapped 90-day path": "自助法得到的 90 天路径",
  "Two prepared quantile bands around a median.": "围绕中位数的两条已备好的分位带。",
  "Range band": "区间带",
  "A centre line with one interval around it. The band is a fill, not two more lines.":
    "一条中心线，外加围绕它的一条区间。这个带是填充，而不是另外两条线。",
  "Estimate with interval": "带区间的估计值",
  "Prepared lower/upper bounds.": "已备好的上下界。",
  "Prepared regression": "已备好的回归",
  "Observations plus a fit the analytics layer already computed — slope and intercept arrive as input.":
    "观测值加上分析层已经算好的拟合——斜率与截距是作为输入传进来的。",
  "Factor regression": "因子回归",
  "Point cloud, fitted line and a confidence band.": "点云、拟合线与一条置信带。",
  "Risk vs return": "风险与收益",
  "Four named quadrants around a reference pair.": "围绕一个参考点划分的四个具名象限。",
  "Risk and return quadrants": "风险与收益象限",
  "Distribution": "分布",
  "Bars, a density overlay and prepared reference levels. Signed samples split into the semantic positive/negative colours.":
    "柱体、一层密度叠加曲线，以及已备好的参考水平线。带符号的样本按语义正/负色拆分。",
  "Forward returns": "远期收益",
  "Pre-binned sample with a kernel density the caller supplied.":
    "预先分箱的样本，配一条由调用方提供的核密度曲线。",
  "Signed daily moves": "带符号的日度变动",
  "The same bins, split by sign — a histogram is not automatically two-coloured.":
    "同样的分箱，按符号拆分——直方图并不会自动变成两种颜色。",
  "Regime strip and event study": "区制条与事件研究",
  "Categorical regimes and dated events on a shared time axis — annotation that answers 'in which regime was this?'.":
    "共享时间轴上的分类区制与带日期的事件——这种标注回答的是「这件事发生在哪个区制里？」",
  "Regime timeline": "区制时间线",
  "Each state keeps its own colour wherever it appears.": "每个状态无论出现在哪里都保持自己的颜色。",
  "Market events": "市场事件",
  "Events grouped by category, each with a dated guide.": "事件按类别分组，每组都有一条带日期的参考线。",
  "Sparse events carry their own labels": "稀疏事件自带标签",
  "`labelMode=\"auto\"` prints each label at its marker while the history is short enough to read, and falls back to markers-only (the tooltip carries the name) once it is not.":
    "`labelMode=\"auto\"` 在历史长度还读得过来时把每个标签印在标记处，一旦读不过来就退化为只显示标记（名称由 tooltip 承载）。",
  "Small multiples": "小多图",
  "One panel per window, shared x semantics — the alternative to an overcrowded single plot.":
    "每个窗口一个面板，共享 x 语义——这是对一张挤满的图的替代方案。",
  "Palettes": "色板",
  "Categorical answers 'which series?', sequential answers 'how much?', diverging answers 'which side?'.":
    "分类色板回答「哪个系列？」，顺序色板回答「多少？」，发散色板回答「哪一侧？」",
  "Categorical · series keys": "分类 · 系列键",
  "A key maps to a stable slot, so filtering a series never repaints the others.":
    "一个键映射到一个固定槽位，因此筛掉某个系列不会让其它系列重新着色。",
  "Sequential · how much": "顺序 · 多少",
  "Interpolated from the theme anchors, so a ramp sits beside the categorical hues.":
    "从主题锚点插值而来，因此色阶能与分类色相并列而不冲突。",
  "Diverging · which side": "发散 · 哪一侧",
  "A low-chroma midpoint, so 'no signal' reads as nothing.":
    "低彩度的中点，因此「没有信号」读起来就是「什么都没有」。",

