  "Smooth": "平滑",
  "Interpolated join, no symbols past 60 points.": "插值连接，超过 60 个点后不再画数据点。",
  "Step": "阶梯",
  "For values that change discretely, such as a policy rate.":
    "用于离散变化的数值，例如政策利率。",
  "Area": "面积",
  "Gradient fill by default; stacking is a property, not a different component.":
    "默认使用渐变填充；堆叠是一个属性，而不是另一个组件。",
  "Gradient area": "渐变面积",
  "A single series, filled toward the axis.": "单条系列，向坐标轴方向填充。",
  "Stacked area": "堆叠面积",
  "Three revenue lines sharing one stack key.": "三条收入曲线共享一个堆叠键。",
  "Range and direction": "区间与方向",
  "A confidence band is a transparent stacked base plus a filled range; positive/negative areas are two series split at zero.":
    "置信带是一条透明的堆叠基座加一条填充区间；正/负面积则是两条在零处拆分的系列。",
  "Confidence band": "置信带",
  "Prepared upper and lower bounds; the chart does not compute them.":
    "已备好的上下界；图表不负责计算它们。",
  "Positive / negative area": "正 / 负面积",
  "Daily change split at zero, ready for a div-based renderer.":
    "在零处拆分的日度变化，可直接交给基于 div 的渲染器。",
  "Gaps, thresholds and events": "缺口、阈值与事件",
  "Missing values are gaps, never zeros; reference lines and event markers are annotations on the same chart.":
    "缺失值是缺口，绝不是零；参考线与事件标记是同一张图上的标注。",
  "Missing values": "缺失值",
  "Null points break the line instead of dropping to the axis.":
    "null 点会断开曲线，而不是掉到坐标轴上。",
  "Thresholds and events": "阈值与事件",
  "A reference line, a reference band and two event markers, all prepared data.":
    "一条参考线、一条参考带与两个事件标记，全部是已备好的数据。",
  "The band trick is worth copying verbatim when you need an envelope.":
    "当你需要一个包络时，这个「带」的做法值得原样照抄。",

  /* -------------------------------------------------------------------- charts/sync */
  "Price": "价格",
  "Realized volatility": "已实现波动率",
  "Close": "收盘",
  "Cross-engine stack": "跨引擎叠放",
  "Move the pointer across any pane. Scroll or drag to change the visible window; all three follow. Each chart publishes only what it owns, and a subscriber never receives its own event.":
    "把指针移到任一窗格上。滚动或拖动改变可见窗口；三个窗格一起跟随。每张图只发布自己拥有的东西，订阅者也永远收不到自己发出的事件。",
  "Lightweight Charts · candlestick, volume pane": "Lightweight Charts · K 线，成交量窗格",
  "Price pane in the synchronised stack": "同步叠放中的价格窗格",
  "Funding rate": "资金费率",
  "Apache ECharts · line with a zero reference": "Apache ECharts · 带零参考线的折线",
  "Apache ECharts · area with a prepared band": "Apache ECharts · 带已备好区间的面积图",
  "Same-engine sync": "同引擎同步",
  "A price line and a volume bar chart sharing a group. The range selector is absent on purpose: the demo is about the crosshair and the window, not about refetching.":
    "一条价格折线与一张成交量柱图共享同一组。这里刻意不放区间选择器：这个演示讲的是十字线与窗口，而不是重新请求数据。",
  "Volume": "成交量",
  "How it works": "如何工作",
  "Two rules do all the work.": "两条规则完成了全部工作。",
  "The bus carries milliseconds and a window. Each adapter converts at its own boundary: ECharts already speaks milliseconds, Lightweight Charts speaks seconds, and nothing downstream has to know that.":
    "总线传递的是毫秒与窗口。每个适配器在自己的边界处换算：ECharts 本来就以毫秒为单位，Lightweight Charts 用秒，下游无需知道这件事。",
  "A publish carries its origin id, and a subscriber never receives its own event. While an adapter applies a remote value it sets a guard so the engine's resulting event is not re-published.":
    "每次发布都带来源 id，订阅者永远收不到自己发出的事件。适配器在应用远端值时会上锁，因此引擎因此产生的事件不会被再次发布。",

