  "Factor exposure vs forward return": "因子暴露与远期收益",
  "Prepared buckets; hover reads both axes.": "已备好的分桶；悬停可读出两个轴的值。",
  "Bubble and connected scatter": "气泡图与连线散点图",
  "Bubble encodes a third prepared value as area; a connected scatter is a line series with symbols, ordered by x.":
    "气泡把第三个已备好的值编码为面积；连线散点则是一条带数据点的折线系列，按 x 排序。",
  "Bubble": "气泡图",
  "Symbol area is proportional to the prepared turnover field.":
    "数据点面积与已备好的成交额字段成正比。",
  "Connected scatter": "连线散点图",
  "Ordered by x, so the path reads as a trajectory.": "按 x 排序，因此路径读起来像一条轨迹。",
  "Regression lines": "回归线",
  "The chart accepts the fit; it never computes it.": "图表接受这个拟合；它从不计算它。",
  "A fitted line is a second series whose data arrives already prepared by the caller. That keeps the chart honest: whatever the model did is visible in the data layer, not hidden inside a renderer.":
    "拟合线是第二条系列，它的数据由调用方备好后传入。这让图表保持诚实：模型做过什么，在数据层里看得见，而不是藏在渲染器内部。",

  /* ------------------------------------------------------------------- charts/radial */
  "Charts · Radial": "图表 · 径向",
  "Radar": "雷达图",

  "Six prepared spokes, three series, low-alpha fills so overlapping shapes stay readable.":
    "六个已备好的轴、三条系列，低 alpha 填充让重叠的形状依然可读。",
  "Strategy profile": "策略画像",
  "Higher is better on every spoke; the axes are normalised by the caller.":
    "每个轴上都是越高越好；轴由调用方归一化。",
  "Radar comparison of three strategy profiles": "三个策略画像的雷达对比",
  "Gauge": "仪表盘",
  "Three compact gauges. Threshold zones are optional and drawn as a track, not as separate dials.":
    "三个紧凑仪表盘。阈值区间是可选的，并且画成一条轨道，而不是另外几个刻度盘。",

