  "Charts · Performance": "图表 · 性能",
  "10,000 points, two engines": "10,000 个点，两个引擎",
  "Both charts below share one deterministic dataset. The notes are local environment observations, not a benchmark claim.":
    "下面两张图共用同一份确定性数据集。这些说明是本地环境的观察结果，不是性能基准声明。",
  "ECharts · 10,000 points": "ECharts · 10,000 个点",
  "Line plus a prepared band, progressive rendering, no intro animation.":
    "折线加一条已备好的区间带，渐进式渲染，没有入场动画。",
  "Ten thousand point time series": "一万个点的时间序列",
  "ECharts · decimated to 2,500": "ECharts · 抽稀到 2,500",
  "The same shape after a caller-side decimation step.": "经过调用方一侧抽稀之后的同一形状。",
  "Prepared envelope at scale": "大规模下的已备好包络",
  "Upper and lower bounds as an area pair, with the series in line.":
    "上下界作为一对面积呈现，曲线本身用折线。",
  "Band at 10,000 points": "10,000 个点上的区间带",
  "The band is drawn with the same transparent-stack technique; no custom renderer is involved.":
    "这条带用的是同一套透明堆叠技术；没有引入任何自定义渲染器。",
  "Envelope at ten thousand points": "一万个点上的包络",
  "What the system does at scale": "系统在大规模下的表现",
  "Rules, not tricks.": "靠规则，不靠技巧。",
  "Latest synthetic value in this dataset:": "这份数据集里最新的合成数值：",
  ". Timings are not published here because a screenshot environment is not a benchmark.":
    "。这里不公布耗时，因为截图环境不是性能基准。",

