  /* ------------------------------------------------------------------ charts/matrix */
  "Correlation matrix": "相关性矩阵",
  "Charts · Matrix": "图表 · 矩阵",
  "Categorical matrix": "分类矩阵",
  "Sequential intensity, generous cell separation and a bottom legend.":
    "顺序强度、宽松的单元格间距，以及底部图例。",
  "Session intensity by weekday": "按星期的时段强度",
  "Values prepared per cell; empty cells stay empty.":
    "每个单元格的值都已备好；空单元格保持为空。",
  "Heatmap of session intensity by weekday": "按星期的时段强度热力图",
  "Diverging palette anchored at zero, symmetric grid, and a coefficient in every cell the reader can actually read. Ink is chosen per cell from the colour underneath it.":
    "以零为中心锚定的发散色板、对称网格，并且在读者确实读得出来的每个单元格里都印上系数。墨色按单元格底下的颜色逐个选取。",
  "Asset correlation": "资产相关性",
  "Ten assets. Past twelve labels the matrix rotates and truncates instead of overlapping.":
    "十个资产。超过十二个之后，矩阵会把标签旋转并截断，而不是让它们重叠。",
  "Correlation matrix across ten assets": "十个资产的相关性矩阵",
  "Small matrix": "小矩阵",
  "Four series in a wide card: the cells are huge, so every coefficient including the diagonal is printed in full.":
    "宽卡片里的四条系列：单元格很大，因此包括对角线在内的每个系数都完整打印。",
  "Cross-asset correlation": "跨资产相关性",
  "A 4×4 matrix at the same card width as the ten-asset case.":
    "与十个资产那一例相同的卡片宽度下的 4×4 矩阵。",
  "Correlation matrix across four assets": "四个资产的相关性矩阵",
  "Label policy": "标签策略",
  "Values are a policy, not a constant. auto prints a coefficient while the cell can hold it — measured from the rendered cell, not the row count — so the same matrix gains and loses its numbers as the card is resized. Hover always carries the pair and the coefficient.":
    "数值显示是一项策略，而不是一个常量。auto 会在单元格装得下时打印系数——依据渲染后的单元格测量，而不是行数——因此同一张矩阵在卡片缩放时会获得或失去数字。悬停时永远带上这一对与系数。",
  "Twenty series, narrow card": "二十条系列，窄卡片",
  "400 cells in a 28rem column — the case auto exists for.":
    "28rem 宽的列里 400 个单元格——这正是 auto 存在的场景。",
  "Correlation matrix across twenty series": "二十条系列的相关性矩阵",
  "Calendar": "日历",
  "One cell per day. Useful for activity and cadence, not for magnitude comparisons.":
    "每天一个单元格。适合看活跃度与节奏，不适合比较量级。",
  "Current cell": "当前单元格",
  "A period matrix has a newest cell, and a reader should not have to count columns to find it. `highlight` marks the cells a caller names as current — the fill keeps saying what the value is, the edge says where the series is now.":
    "周期矩阵总有一个最新的单元格，读者不该靠数列来找它。`highlight` 会标记调用方指定为当前的单元格——填充继续表示数值是多少，边缘则表示系列现在在哪里。",
  "Quarterly returns with the current quarter marked": "季度收益，并标出当前季度",
  "The empty cell is the quarter still running; it is marked so it cannot read as a completed historical period.":
    "那个空单元格是尚未走完的季度；它被标记出来，因此不会被误读为一个已完结的历史区间。",
  "Quarterly returns, current quarter marked": "季度收益，标出当前季度",
  "Both matrix components take prepared values, never a dataframe.":
    "两个矩阵组件接收的都是已备好的值，绝不是 dataframe。",

  /* ------------------------------------------------------------- charts/interaction */
  "Scale": "刻度",
  "Charts · Interaction": "图表 · 交互",
  "Tooltip modes": "Tooltip 模式",
  "Axis tooltips for time series, item tooltips for marks, and an explicit off switch.":
    "时间序列用轴 tooltip，图元用条目 tooltip，并提供一个显式的关闭开关。",
  "Axis tooltip": "轴 tooltip",
  "One date header, one aligned row per visible series.":
    "一个日期表头，每条可见系列一行对齐的记录。",
  "Item tooltip": "条目 tooltip",
  "Used where there is no shared x: bars, scatter, heatmap, flow.":
    "在没有共享 x 轴的地方使用：柱图、散点、热力图、流向图。",
  "Zoom and brush": "缩放与框选",
  "Wheel zoom is opt-in per chart; brush selection is opt-in and stays a research affordance.":
    "滚轮缩放按图表逐个启用；框选也是可选的，并且始终只作为研究用途。",
  "Zoom inside": "在内部缩放",
  "Wheel to zoom, drag to pan. Scroll hijacking is limited to the plot itself.":
    "滚轮缩放、拖动平移。对滚动的劫持仅限于绘图区本身。",
  "Brush": "框选",
  "Drag inside the plot to select a subrange; the toolbar clears it.":
    "在绘图区内拖动以选择子区间；工具条可清除它。",
  "Linear or logarithmic is a presentation choice over the same values: the axis maps them, the data never changes, and a range change never re-scales the chart silently.":
    "线性还是对数，是对同一批数值的呈现选择：轴负责映射，数据本身不变，切换区间也从不悄悄重算图表。",
  "Long-horizon price": "长周期价格",
  "Log is the declared default for a series spanning four orders of magnitude; the reader may switch to Linear and the choice sticks.":
    "跨越四个数量级的序列默认声明为对数；读者可以切到线性，而且这个选择会记住。",
  "Signed measurement": "带符号的度量",
  "A drawdown is linear-only: a log axis over a value that reaches zero would be a broken chart, so the renderer offers no control at all.":
    "回撤只能线性：在一个会取到零的值上套对数轴就是一张坏图，因此渲染器干脆不提供这个控件。",
  "Fullscreen research view": "全屏研究视图",
  "The fullscreen button on every panel above opens a real workspace, not a stretched div. Escape exits; focus returns to the trigger. The selected scale, range and series travel with it.":
    "上面每个面板上的全屏按钮都会打开一个真正的工作区，而不是一个被拉长的 div。Escape 退出；焦点回到触发元素。所选的刻度、区间与系列都会一起带过去。",
  "Fullscreen research": "全屏研究",
  "Title, latest readout, range, legend, export and a chart that fills the remaining height.":
    "标题、最新读数、区间、图例、导出，以及一张填满剩余高度的图表。",
  "Deferred": "已延后",
  "One interaction that did not ship this round.": "一项本轮没有交付的交互。",
  "Click-to-pin a tooltip for comparison belongs with the research workspace work: it needs a visible pin affordance, an unpin gesture, and a decision about what happens when the pinned x scrolls out of view. The transient tooltip already covers reading a single value.":
    "用于对比的「点击钉住 tooltip」属于研究工作区那项工作：它需要一个可见的钉住入口、一个取消钉住的手势，以及决定被钉住的 x 滚出视野时该怎么办。临时 tooltip 已经覆盖了读单个值的场景。",

