  /* --------------------------------------------- industry vignettes (patterns) */
  "Migrate the serving layer to V3": "把服务层迁移到 V3",
  "Agent run · 4 min 12 s · 18,402 tokens": "智能体运行 · 4 分 12 秒 · 18,402 tokens",
  "Tell the agent what to change next…": "告诉智能体下一步改什么…",
  "Auto-apply patches": "自动应用补丁",
  "The workshop where every prototype is allowed to fail": "一个允许每个原型都失败的工作坊",
  "Most of what leaves this room is wrong. That is the arrangement: a prototype is a question, and the only prototype worth keeping is one that answers it in under a week.":
    "从这里出去的东西大部分都是错的，而这正是约定：原型是一个问题，唯一值得留下的原型，是在一周之内回答了它的那一个。",
  "Studio lead · 8 min read": "工作室负责人 · 8 分钟阅读",
  "“A prototype that takes a month is a decision you have already made.”":
    "「花一个月做出来的原型，其实是你早就做完的决定。」",
  "Sleeve attribution": "分组归因",
  "Weight and contribution by sleeve.": "按分组统计权重与贡献。",

