  "Study": "研究",
  "The charts state their units": "图表会写明单位",
  "The figure beside this text is the catalog itself, counted by area of the site. It is the only dataset the front door owns, so it cannot drift from what it describes.": "旁边的图表就是本目录本身，按站点区域计数。这是首页唯一拥有的数据集，因此它不可能与所描述的内容发生偏离。",
  "The tokens, the spacing rhythm and the rules a page is built from.": "令牌、间距节奏，以及页面据以构建的规则。",
  "Use case": "用例",
  "Visuals": "视觉",
