  "Layering": "层级",
  "A button that keeps its pressed state: formatting, column sets, and any on/off that is not a switch.": "一种会记住按下状态的按钮：格式设置、列集合，以及一切不属于开关的开/关。",
  "Pressed and unpressed": "按下与未按下",
  "A group: multiple or single": "成组：多选或单选",
