  "Search {count} icons by name or keyword": "按名称或关键词搜索 {count} 个图标",
  "Search the icon set": "搜索图标集",
  "{found} of {total} icons": "{total} 个图标中的 {found} 个",
  "No icon matches that word. Try a broader one, in English or Chinese.": "没有匹配该词的图标。请换一个更宽泛的词，中英文均可。",
  "Five sizes": "五种尺寸",
  "A size is a role, not a pixel count: `xs` is inline in text, `xl` is a mark.": "尺寸是一种角色，而不是像素数字：`xs` 用于行内文字，`xl` 是一个标记。",
  "Tones, and a name when the icon is the content": "色调，以及当图标本身就是内容时的名称",
  "The set, searchable": "可搜索的图标集",
  "Names and keywords in both languages, because the person looking for an icon may type either one.": "名称与关键词都提供中英文两种，因为找图标的人可能输入任意一种。",
