  "8 symbols · annualised 6.1%": "8 个标的 · 年化 6.1%",
  "Provider returned 503 for the last session": "提供商在最近一个交易时段返回 503",
  "A real list, not a column of cards: one hairline between rows, and the same five slots on every row so the eye can run down the column.": "是真正的列表，而不是一列卡片：行与行之间只有一条细分隔线，每行都是同样五个槽位，目光可以顺着这一列扫下去。",
  "Edges and a count": "首尾与计数",
  "Showing 2 of 1,284": "共 1,284 条，显示 2 条",
  "The header and footer are the list's own edges — a title with the one action it is about, and the count that says whether to keep reading.": "页眉与页脚属于列表自身：标题配上它所对应的那一个操作，以及告诉读者是否还需要继续往下看的计数。",
  "Symbols without a frame": "没有外框的标的列表",
  "1h · 1,284 bars": "1h · 1,284 根 K 线",
  "Without `bordered` the list is just the rows, which is what a panel or a sidebar wants.": "不加 `bordered` 时，列表就只是这些行，这正是面板或侧栏需要的形态。",
  "1,284 bars were written for BTCUSDT 1h, and the series is ready to chart.": "已为 BTCUSDT 1h 写入 1,284 根 K 线，该序列可以绘图了。",
  "Every status": "所有状态",
  "All seven domains matched.": "七个领域全部匹配。",
  "The provider returned 503.": "提供商返回了 503。",
