  "One wrapper for the library's glyphs: size, tone and accessibility settled in one place, plus the named set it draws with.": "库内字形的统一包装：尺寸、色调与无障碍在一处定好，并附带它绘制时所用的具名图标集。",
  "An action that stays reachable: pinned to a corner, with the offsets, stacking and disclosure a stack of them needs.": "始终可达的操作：固定在某个角落，并带有一组操作所需的偏移、层叠与展开行为。",
  "The surface a flow ends on: what just happened, what to do next, and the action that follows from it.": "流程结束时呈现的表面：刚刚发生了什么、接下来该做什么，以及随之而来的操作。",
  "A sequence of comparable rows on one hairline grid, with the slots that keep ten rows aligned.": "在同一套细分隔线上排列的可比较行序列；槽位固定，十行也能对齐。",

  "Personal-site sections — a profile hero, a career timeline, publications, a reading shelf, /now — are documented with the components they are made of, and composed end to end in Experiences.": "个人主页类版块——个人简介头图、经历时间线、论文列表、在读清单、/now——随它们所用的组件一起提供文档，并在 Experiences 中端到端组合演示。",

