  "A row of metrics using the numeric formatter, so units and separators stay consistent.": "一行使用数字格式化器的指标，单位与分隔符因此保持一致。",
  "A titled section with one action — what most console pages need instead of a toolbar.": "带标题、只含一个操作的区块——大多数控制台页面需要的正是它，而不是一条工具栏。",
  "A name as the page h1, one line of context, and the facts a reader wants first.": "以姓名作为页面 h1、一行背景说明，以及读者最先想知道的事实。",
  "Roles as an ordered list, with a machine-readable period and an open end for the current one.": "把经历排成有序列表：时间段可被机器读取，当前一段留开放结尾。",
  "Publications with a real author line and venue, and no invented citation counts.": "论文带着真实的作者署名与发表刊物，不虚构引用次数。",
  "A /now block that must carry the date it was last true.": "一个 /now 区块，必须带上它最后成立的那一天。",
  "Recent events as a timeline, with the timestamps the caller supplies.": "近期事件排成时间线，时间戳由调用方提供。",
  "Your own headline, subhead and destination for the two links.": "你自己的主标题、副标题，以及两个链接的去向。",
  "A list of { title, body } pairs.": "一组 { title, body } 键值对。",
  "Your pricing model — or, as here, an honest statement that it does not exist yet.": "你的定价模型——或者像这里一样，如实说明它还不存在。",
  "Numeric values: a formatted string is not a number the component can align.": "数值：格式化过的字符串不是组件能对齐的数字。",
  "A number and a format kind (`number`, `percent`, `currency`, `compact`).": "一个数字和一个格式类型（`number`、`percent`、`currency`、`compact`）。",
  "A title, a description and the actions your page actually has.": "一个标题、一段描述，以及你页面真正拥有的操作。",
  "A name, a title and the facts list; `ProfileHero` owns the heading order.": "姓名、头衔和事实清单；标题层级由 `ProfileHero` 决定。",
  "Entries with { role, org, from, to? }; mark the current role with `current`.": "条目形如 { role, org, from, to? }；用 `current` 标出当前职位。",
  "Entries with { title, authors, venue, year }; facets are derived from the data.": "条目形如 { title, authors, venue, year }；筛选维度由数据推导。",
  "Entries with { title, author, status } and an optional 0–1 progress.": "条目形如 { title, author, status }，进度为可选的 0–1。",
  "The `updatedAt` date — the component requires it, so the section cannot go stale silently.": "`updatedAt` 日期——组件要求必填，因此该区块不会悄悄过期。",
  "Your roles, projects and the CV you are willing to publish.": "你的经历、项目，以及你愿意公开的简历。",
  "A publication list with author lines exactly as the venues print them.": "论文列表，作者署名按刊物原样呈现。",
  "Cover media, project copy and the links a visitor should follow.": "封面素材、项目文案，以及访客应该点进去的链接。",
  "Entries and their real dates; the /now timestamp is required by the component.": "条目及其真实日期；组件要求 /now 的时间戳必填。",
  "Your claims, your proof and a destination for the form.": "你的主张、你的证据，以及表单提交的去向。",
  "Columns, data and the actions that change them.": "列、数据，以及会改动它们的操作。",
  "Articles, topics and a canonical URL per piece.": "文章、主题，以及每篇的规范链接。",
  "A real dataset and the metric definitions behind it.": "一份真实数据集，以及它背后的指标定义。",
  "A chart measures its container, so it always needs a definite height.": "图表会测量自己的容器，因此始终需要一个确定的高度。",
  "The surface the chart is in — loading, empty and error are drawn by the component.": "图表所处的表面——加载、空态与错误由组件自己绘制。",
  "A drawing is not readable by a screen reader, so it needs a name that states what it shows.": "图形本身无法被屏幕阅读器读取，因此需要一个说明它画了什么的名字。",
  "The same fixture as the live preview above; the controls change how it is drawn, not what it measures.": "与上方实时预览使用同一份固定数据；控件改变的是画法，而不是它度量的内容。",
  "The numbers are the caller's; the fixture above is the example.": "数字由调用方提供；上方的固定数据只是示例。",


